  shaft.quaternion.copy(q); head.quaternion.copy(q);
  shaft.position.copy(dv).multiplyScalar(sl * 0.5);
  head.position.copy(dv).multiplyScalar(sl + headL * 0.5);
  g.position.copy(origin);
}
function addArcTube(group, pts, color, tubeR, withHead, headL) {
  const mat = new THREE.MeshStandardMaterial({
    color, roughness: 0.6, metalness: 0, depthTest: false, depthWrite: false
  });
  const curve = new THREE.CatmullRomCurve3(pts);
  const mesh = new THREE.Mesh(new THREE.TubeGeometry(curve, Math.max(12, pts.length * 2), tubeR, 8, false), mat);
  mesh.renderOrder = 6; group.add(mesh);
  if (withHead) {
    const hl = headL || 0.22, hr = (headL || 0.22) * 0.44;
    const p1 = pts[pts.length - 1], p0 = pts[pts.length - 2];
    const dv = p1.clone().sub(p0).normalize();
    const cone = new THREE.Mesh(new THREE.ConeGeometry(hr, hl, 16), mat);
    cone.quaternion.setFromUnitVectors(UPV, dv);
    cone.position.copy(p1).add(dv.clone().multiplyScalar(hl * 0.45));
    cone.renderOrder = 6; group.add(cone);
  }
  return mesh;
}
function addPlainLine(group, pts, color, opts = {}) {
  const mat = opts.dashed
    ? new THREE.LineDashedMaterial({ color, dashSize: 0.17, gapSize: 0.13, depthTest: false })
    : new THREE.LineBasicMaterial({ color, depthTest: false, transparent: !!opts.opacity, opacity: opts.opacity ?? 1 });
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat);
  if (opts.dashed) line.computeLineDistances();
  line.renderOrder = 5; group.add(line);
  return line;
}

/* ── coordinate axes ──────────────────────────────────────────────────── */
const axesGroup = new THREE.Group(); scene.add(axesGroup);
const axOpt = { shaftR: 0.016, headL: 0.24, headR: 0.075, order: 4 };
const axZ = makeArrow(C.black, axOpt); axesGroup.add(axZ); setArrow(axZ, ORIGIN, UPV, 6.0);
const axY = makeArrow(C.black, axOpt); axesGroup.add(axY); setArrow(axY, ORIGIN, new THREE.Vector3(1, 0, 0), 3.5);
const axX = makeArrow(C.black, axOpt); axesGroup.add(axX); setArrow(axX, ORIGIN, new THREE.Vector3(0, 0, 1), 2.5);

/* ── precession / tilt hierarchy ──────────────────────────────────────── */
const precessGroup = new THREE.Group(); scene.add(precessGroup);
const tiltGroup = new THREE.Group(); precessGroup.add(tiltGroup);

/* ── the top: teardrop lathe bands ────────────────────────────────────── */
const BODY_LEN = 3.30;
const profCtl = [[0, 0], [0.15, 0.07], [0.35, 0.17], [0.60, 0.30], [0.90, 0.47],
[1.20, 0.64], [1.50, 0.79], [1.80, 0.91], [2.05, 0.985], [2.25, 1.00],
[2.50, 0.99], [2.75, 0.955], [3.00, 0.905], [3.15, 0.875], [3.30, 0.86]];
function radAt(h) {
  if (h <= 0) return 0;
  for (let i = 1; i < profCtl.length; i++) {
    if (h <= profCtl[i][0]) {
      const a = profCtl[i - 1], b = profCtl[i];
      const t = (h - a[0]) / (b[0] - a[0]);
      return a[1] + (b[1] - a[1]) * t;
    }
  }
  return profCtl[profCtl.length - 1][1];
}
const CAP_R = radAt(BODY_LEN);
const bodyGroup = new THREE.Group(); tiltGroup.add(bodyGroup);
const bands = [
  { h0: 0.00, h1: 1.55, c: C.blue },
  { h0: 1.55, h1: 2.35, c: C.band },
  { h0: 2.35, h1: 3.05, c: C.blue },
  { h0: 3.05, h1: 3.30, c: C.blueLt }
];
bands.forEach(b => {
  const pts = [];
  const n = 18;
  for (let i = 0; i <= n; i++) {
    const h = b.h0 + (b.h1 - b.h0) * (i / n);
    pts.push(new THREE.Vector2(Math.max(radAt(h), 1e-4), h));
  }
  const mesh = new THREE.Mesh(
    new THREE.LatheGeometry(pts, 72),
    new THREE.MeshStandardMaterial({ color: b.c, roughness: 0.52, metalness: 0.04, side: THREE.DoubleSide })
  );
  bodyGroup.add(mesh);
});
const capMesh = new THREE.Mesh(
  new THREE.CircleGeometry(CAP_R, 72),
  new THREE.MeshStandardMaterial({ color: C.blueLt, roughness: 0.5, side: THREE.DoubleSide })
);
capMesh.rotation.x = -Math.PI / 2; capMesh.position.y = BODY_LEN; bodyGroup.add(capMesh);

/* stem — larger and lighter so it reads clearly */
const STEM_R = 0.24, STEM_H = 0.80;
const stem = new THREE.Mesh(
  new THREE.CylinderGeometry(STEM_R, STEM_R, STEM_H, 32),
  new THREE.MeshStandardMaterial({ color: C.blueVLt, roughness: 0.42, metalness: 0.05 })
);
stem.position.y = BODY_LEN + STEM_H / 2; tiltGroup.add(stem);
const stemCap = new THREE.Mesh(
  new THREE.CircleGeometry(STEM_R, 32),
  new THREE.MeshStandardMaterial({ color: 0xdff0f6, roughness: 0.42, side: THREE.DoubleSide })
);
stemCap.rotation.x = -Math.PI / 2; stemCap.position.y = BODY_LEN + STEM_H; tiltGroup.add(stemCap);

/* green spin loop ω hugging the stem */
const SPIN_H = BODY_LEN + 0.40;
const spinGroup = new THREE.Group(); tiltGroup.add(spinGroup);
(function buildSpinLoop() {
  const pts = [];
  const R = STEM_R + 0.14;
  const a0 = THREE.MathUtils.degToRad(25), a1 = a0 + THREE.MathUtils.degToRad(300);
  for (let i = 0; i <= 48; i++) {
    const a = a0 + (a1 - a0) * (i / 48);
    pts.push(new THREE.Vector3(R * Math.cos(a), SPIN_H, -R * Math.sin(a)));
  }
  addArcTube(spinGroup, pts, C.green, 0.026, true, 0.20);
})();

/* ── vectors parented to the precession group ─────────────────────────── */
const rArrow = makeArrow(C.black, { shaftR: 0.055, headL: 0.34, headR: 0.135 });
const mgArrow = makeArrow(C.red, { shaftR: 0.035, headL: 0.26, headR: 0.10 });
const tauArrow = makeArrow(C.vec, { shaftR: 0.035, headL: 0.26, headR: 0.10 });
const LArrow = makeArrow(C.vec, { shaftR: 0.042, headL: 0.30, headR: 0.115 });
const radArrow = makeArrow(C.vec, { shaftR: 0.033, headL: 0.26, headR: 0.10 });
const dLArrow = makeArrow(C.vec, { shaftR: 0.033, headL: 0.24, headR: 0.095 });
precessGroup.add(rArrow, mgArrow, tauArrow, LArrow, radArrow, dLArrow);

/* CM cross */
const cmCross = new THREE.Group(); precessGroup.add(cmCross);
(function buildCross() {
  const mat = new THREE.MeshStandardMaterial({ color: C.black, roughness: 0.5, depthTest: false, depthWrite: false });
  [[1, 0, 1], [1, 0, -1]].forEach(dv => {
    const dvec = new THREE.Vector3(dv[0], dv[1], dv[2]).normalize();
    const bar = new THREE.Mesh(new THREE.CylinderGeometry(0.024, 0.024, 0.34, 10), mat);
    bar.quaternion.setFromUnitVectors(UPV, dvec);
    bar.renderOrder = 7;
    cmCross.add(bar);
  });
})();

/* dynamic arc containers */
const arcsP = new THREE.Group(); precessGroup.add(arcsP);   // rotates with precession
const arcsW = new THREE.Group(); scene.add(arcsW);          // fixed in world

/* τ leader line */
const LEADER_END = new THREE.Vector3(2.60, 0.55, -1.35);
const leader = new THREE.Line(new THREE.BufferGeometry(),
  new THREE.LineBasicMaterial({ color: C.black, depthTest: false }));
leader.renderOrder = 6; scene.add(leader);

/* ── state ────────────────────────────────────────────────────────────── */
const Lmag = 4.8, rCM = 1.9, L_START = 2.60;
let theta = THREE.MathUtils.degToRad(25);
let torque = 1.0;
let phase = 0;
let playing = false;
let cmP = new THREE.Vector3(), axisP = new THREE.Vector3(), tipP = new THREE.Vector3();
let dphiVal = 0, Rcircle = 0, Hcircle = 0;

/* anchors for labels */
function anchor(parent) { const o = new THREE.Object3D(); parent.add(o); return o; }
const aCM = anchor(precessGroup), aTheta = anchor(precessGroup), aL = anchor(precessGroup),
  aR = anchor(precessGroup), aMg = anchor(precessGroup), aTau = anchor(precessGroup),
  aLsin = anchor(precessGroup), aDphi = anchor(precessGroup), adL = anchor(precessGroup),
  aOmega = anchor(tiltGroup), aOmegaP = anchor(scene);
aOmega.position.set(-(STEM_R + 0.60), SPIN_H + 0.05, 0.22);

/* ── rebuild everything that depends on θ and τ ───────────────────────── */
function rebuild() {
  const s = Math.sin(theta), c = Math.cos(theta);
  axisP.set(s, c, 0);
  const perp = new THREE.Vector3(c, -s, 0);           // in the lean plane, screen-right
  const tauDir = new THREE.Vector3(0, 0, -1);         // r̂ × (−ẑ)
  tiltGroup.rotation.z = -theta;

  cmP.copy(axisP).multiplyScalar(rCM);
  setArrow(rArrow, ORIGIN, axisP, rCM);
  cmCross.position.copy(cmP);
  cmCross.rotation.set(0, 0, -theta);
  setArrow(mgArrow, cmP, DOWNV, 1.0);
  const tauLen = 1.1 * torque;
  setArrow(tauArrow, cmP, tauDir, tauLen);
  setArrow(LArrow, axisP.clone().multiplyScalar(L_START), axisP, Lmag - L_START);

  Rcircle = Lmag * s; Hcircle = Lmag * c;
  tipP.set(Rcircle, Hcircle, 0);
  setArrow(radArrow, new THREE.Vector3(0, Hcircle, 0), new THREE.Vector3(1, 0, 0), Rcircle);
  const dLlen = 0.5 * torque;
  setArrow(dLArrow, tipP, tauDir, dLlen);
  dphiVal = Math.min(dLlen / Rcircle, 1.1);

  clearGroup(arcsP); clearGroup(arcsW);

  // θ arc at the origin (in the lean plane)
  const tp = [];
  for (let i = 0; i <= 26; i++) { const a = theta * i / 26; tp.push(new THREE.Vector3(0.8 * Math.sin(a), 0.8 * Math.cos(a), 0)); }
  addArcTube(arcsP, tp, C.black, 0.017, false);

  // faint advanced radius + dφ arc
  const adv = new THREE.Vector3(Rcircle * Math.cos(dphiVal), Hcircle, -Rcircle * Math.sin(dphiVal));
  addPlainLine(arcsP, [new THREE.Vector3(0, Hcircle, 0), adv], C.faint, { opacity: 0.75 });
  const ap = [];
  const ar = Math.min(0.9, Rcircle * 0.55);
  for (let i = 0; i <= 18; i++) {
    const a = dphiVal * i / 18;
    ap.push(new THREE.Vector3(ar * Math.cos(a), Hcircle, -ar * Math.sin(a)));
  }
  addArcTube(arcsP, ap, C.black, 0.015, false);

  // dashed precession circle (fixed in world)
  const cp = [];
  for (let i = 0; i <= 160; i++) {
    const a = (i / 160) * Math.PI * 2;
    cp.push(new THREE.Vector3(Rcircle * Math.cos(a), Hcircle, -Rcircle * Math.sin(a)));
  }
  addPlainLine(arcsW, cp, C.black, { dashed: true });

  // ω_p curved arrow, upper-left, around z
  const wp = [];
  const wH = Hcircle + 1.0, wR = 2.4;
  for (let i = 0; i <= 40; i++) {
    const a = THREE.MathUtils.degToRad(112 + (138 * i / 40));
    wp.push(new THREE.Vector3(wR * Math.cos(a), wH, -wR * Math.sin(a)));
  }
  addArcTube(arcsW, wp, C.black, 0.028, true, 0.26);
  aOmegaP.position.set(-wR - 0.55, wH - 0.20, 0.55);

  // label anchors — pushed outward, mostly along the perpendicular of the lean plane
  aCM.position.copy(cmP).add(OUT.clone().multiplyScalar(0.72)).add(new THREE.Vector3(0, 0.10, 0));
  const half = theta / 2;
  aTheta.position.set(1.05 * Math.sin(half), 1.05 * Math.cos(half), 0).add(OUT.clone().multiplyScalar(0.40));
  aL.position.copy(axisP).multiplyScalar(3.90).add(perp.clone().multiplyScalar(0.38));
  aR.position.copy(axisP).multiplyScalar(1.05).add(OUT.clone().multiplyScalar(0.70)).add(perp.clone().multiplyScalar(-0.15));
  aMg.position.copy(cmP).add(new THREE.Vector3(0, -0.62, 0)).add(OUT.clone().multiplyScalar(-0.55));
  aTau.position.copy(cmP).add(tauDir.clone().multiplyScalar(tauLen * 0.65)).add(new THREE.Vector3(0, 0.22, 0));
  aLsin.position.set(Rcircle * 0.52, Hcircle, 0);
  aDphi.position.set(ar * Math.cos(dphiVal * 0.5) * 1.15, Hcircle, -ar * Math.sin(dphiVal * 0.5) * 1.15);
  adL.position.copy(tipP).add(tauDir.clone().multiplyScalar(dLlen + 0.10));

  const ro = document.getElementById('readout');
  if (ro) {
    ro.innerHTML =
      '|L| = ' + Lmag.toFixed(2) + '  (constant)<br>' +
      'L sin θ = ' + Rcircle.toFixed(2) + '<br>' +
      '|dL| = τ dt = ' + dLlen.toFixed(2) + '<br>' +
      'dφ = |dL|/(L sinθ) = ' + THREE.MathUtils.radToDeg(dphiVal).toFixed(1) + '°<br>' +
      'ω_p ∝ τ / L = ' + (0.62 * torque).toFixed(2);
  }
}

/* ── camera, then labels ──────────────────────────────────────────────── */
rebuild();
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.72 });
document.getElementById('btnReset').style.display = '';

const lz = addLabel('<i><b>z</b></i>', new THREE.Vector3(0, 6.28, 0), { fontSize: '16px', bold: true, offset: [-13, -4] });
const ly = addLabel('<i><b>y</b></i>', new THREE.Vector3(3.72, 0, 0), { fontSize: '16px', bold: true, offset: [13, 9] });
const lx = addLabel('<i><b>x</b></i>', new THREE.Vector3(0, 0, 2.78), { fontSize: '16px', bold: true, offset: [-7, 15] });
const lO = addLabel('<i>O</i>', new THREE.Vector3(0, 0, 0), { fontSize: '15px', offset: [-17, 15] });

const lCM = addLabel('CM', new THREE.Vector3(), { fontSize: '14px', offset: [-16, -10] });
const lTheta = addLabel('<i>&theta;</i>', new THREE.Vector3(), { fontSize: '15px', offset: [8, 2] });
const lOmega = addLabel('<i>&omega;</i>', new THREE.Vector3(), { fontSize: '15px', color: '#5f7f1f', offset: [-10, 0] });
const lOmegaP = addLabel('<i>&omega;</i><sub><i>p</i></sub>', new THREE.Vector3(), { fontSize: '15px', offset: [-16, 0] });
const lL = addLabel('<b><i>L</i></b>&#8407;', new THREE.Vector3(), { fontSize: '17px', color: '#EF8420', bold: true, offset: [17, 4] });
const lr = addLabel('<b><i>r</i></b>&#8407;', new THREE.Vector3(), { fontSize: '17px', bold: true, offset: [-14, 2] });
const lMg = addLabel('<i>M</i><b><i>g</i></b>&#8407;', new THREE.Vector3(), { fontSize: '16px', color: '#C0392B', offset: [26, 0] });
const lTau = addLabel('<b><i>&tau;</i></b>&#8407;', new THREE.Vector3(), { fontSize: '17px', color: '#EF8420', offset: [10, -14] });
const lLsin = addLabel('<i>L</i> sin<i>&theta;</i>', new THREE.Vector3(), { fontSize: '13px', offset: [-8, 18] });
const lDphi = addLabel('<i>d&phi;</i>', new THREE.Vector3(), { fontSize: '13px', offset: [4, -15] });
const ldL = addLabel('<i>d</i><b><i>L</i></b>&#8407; = <b><i>&tau;</i></b>&#8407; <i>dt</i>',
  new THREE.Vector3(), { fontSize: '14px', color: '#EF8420', offset: [60, 2] });
const lTauEq = addLabel('<b><i>&tau;</i></b>&#8407; = <b><i>r</i></b>&#8407; &times; <i>M</i><b><i>g</i></b>&#8407;',
  LEADER_END.clone(), { fontSize: '14px', offset: [62, 6] });

/* ── interactive explanations ─────────────────────────────────────────── */
registerInteractive(bodyGroup, {
  title: 'The spinning top',
  tooltip: 'The top: a teardrop body of revolution leaning by θ',
  body: 'The top is a solid of revolution — pointed at the pivot O, widest near its upper third, with a flat top face. It spins rapidly about its own symmetry axis, which is tilted by θ from the vertical, so its whole angular momentum L lies (to a good approximation) along that axis.'
});
registerInteractive(stem, {
  title: 'Stem and spin ω',
  tooltip: 'ω — the spin about the symmetry axis',
  body: 'The green loop around the stem shows the sense of the rapid spin ω about the symmetry axis. This spin is what supplies the large angular momentum L that gravity can only redirect, not topple.'
});
registerInteractive(LArrow, {
  title: 'Angular momentum L',
  tooltip: 'L⃗ — constant magnitude, changing direction',
  body: 'L points along the spin axis with |L| = 4.8 (fixed here). Because the torque is always perpendicular to L, only the direction of L changes: its tip travels on the dashed horizontal circle of radius L sin θ.'
});
registerInteractive(tauArrow, {
  title: 'Torque τ = r × M g',
  tooltip: 'τ⃗ — horizontal, perpendicular to r and to g',
  body: 'Gravity acts at the CM with moment arm r. The cross product r × Mg is horizontal and perpendicular to the plane containing the axis and the vertical, so it pushes L sideways rather than down.'
});
registerInteractive(mgArrow, {
  title: 'Weight M g',
  tooltip: 'M g⃗ — straight down at the CM',
  body: 'The entire weight acts at the centre of mass, a distance r = 1.9 from the pivot O. Its magnitude sets the torque, τ = M g r sin θ.'
});
registerInteractive(rArrow, {
  title: 'Position vector r',
  tooltip: 'r⃗ — from pivot O to the CM',
  body: 'r runs from the fixed contact point O to the centre of mass along the symmetry axis, making the angle θ with the vertical z axis.'
});

/* ── UI wiring ────────────────────────────────────────────────────────── */
const sTheta = document.getElementById('sTheta');
const sTorque = document.getElementById('sTorque');
const thetaVal = document.getElementById('thetaVal');
const torqueVal = document.getElementById('torqueVal');
const btnPlay = document.getElementById('btnPlay');

function syncUI() {
  thetaVal.textContent = Math.round(THREE.MathUtils.radToDeg(theta)) + '°';
  torqueVal.textContent = torque.toFixed(2);
  sTheta.value = String(THREE.MathUtils.radToDeg(theta));
  sTorque.value = String(torque);
  btnPlay.textContent = playing ? '⏸ Pause precession' : '▶ Play precession';
  btnPlay.classList.toggle('active', playing);
}
sTheta.addEventListener('input', () => {
  tween = null;
  theta = THREE.MathUtils.degToRad(parseFloat(sTheta.value));
  rebuild(); syncUI();
});
sTorque.addEventListener('input', () => {
  tween = null;
  torque = parseFloat(sTorque.value);
  rebuild(); syncUI();
});
btnPlay.addEventListener('click', () => { playing = !playing; syncUI(); });

/* guided steps */
const STEPS = [
  {
    title: '1. Static construction',
    text: 'The top leans by θ from the vertical. r runs from the pivot O to the CM, gravity Mg pulls straight down there, and τ = r × Mg points horizontally, perpendicular to both.',
    state: { theta: 25, torque: 1, precess: false }
  },
  {
    title: '2. The dL step',
    text: 'Because τ is perpendicular to L, the increment dL = τ dt is tangent to the dashed circle of radius L sin θ. The tip of L turns through dφ = dL /(L sin θ) without L getting longer.',
    state: { theta: 25, torque: 1.6, precess: false }
  },
  {
    title: '3. Increase the lean',
    text: 'Raising θ widens the circle L sin θ and increases gravity’s moment arm; watch how both the radius and the angular step dφ respond.',
    state: { theta: 50, torque: 1, precess: false }
  },
  {
    title: '4. Let it precess',
    text: 'Run the motion: L keeps a constant length and constant tilt while its tip sweeps the circle at ω_p = Mgr/L — the whole top rotates about the vertical.',
    state: { theta: 30, torque: 1, precess: true }
  }
];
let stepIdx = 0;
let tween = null;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  document.getElementById('stepTitle').textContent = st.title;
  document.getElementById('stepText').textContent = st.text;
  tween = {
    t: 0, dur: 0.75,
    fromT: theta, toT: THREE.MathUtils.degToRad(st.state.theta),
    fromQ: torque, toQ: st.state.torque
  };
  playing = !!st.state.precess;
  syncUI();
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));

/* ── per-frame updates (labels, phase, leader) ────────────────────────── */
const _wp = new THREE.Vector3();
function setLbl(entry, anc) { entry.pos.copy(anc.getWorldPosition(_wp)); }

function updateLeader() {
  const tauTip = cmP.clone()
    .add(new THREE.Vector3(0, 0, -1).multiplyScalar(1.1 * torque))
    .applyAxisAngle(UPV, phase);
  const ctrl = new THREE.Vector3(
    tauTip.x + 0.60, tauTip.y - 1.05, tauTip.z - 0.30
  );
  const curve = new THREE.QuadraticBezierCurve3(tauTip, ctrl, LEADER_END);
  const pts = curve.getPoints(30);
  leader.geometry.dispose();
  leader.geometry = new THREE.BufferGeometry().setFromPoints(pts);
}

let lastT = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - lastT) / 1000);
  lastT = now;

  if (tween) {
    tween.t += dt;
    const u = Math.min(1, tween.t / tween.dur);
    const e = u < 0.5 ? 2 * u * u : -1 + (4 - 2 * u) * u;
    theta = tween.fromT + (tween.toT - tween.fromT) * e;
    torque = tween.fromQ + (tween.toQ - tween.fromQ) * e;
    rebuild(); syncUI();
    if (u >= 1) tween = null;
  }

  if (playing) {
    phase += 0.62 * torque * dt;   // ω_p ∝ τ / L, independent of θ
    if (phase > Math.PI * 2) phase -= Math.PI * 2;
  }
  precessGroup.rotation.y = phase;
  spinGroup.rotation.y -= 3.2 * dt; // visual spin sense of ω

  scene.updateMatrixWorld(true);
  setLbl(lCM, aCM); setLbl(lTheta, aTheta); setLbl(lOmega, aOmega);
  setLbl(lOmegaP, aOmegaP); setLbl(lL, aL); setLbl(lr, aR); setLbl(lMg, aMg);
  setLbl(lTau, aTau); setLbl(lLsin, aLsin); setLbl(lDphi, aDphi); setLbl(ldL, adL);
  updateLeader();
}
syncUI();
goToStep(0);
tick();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

