<div style="font-size:10px;color:#666;line-height:1.35">Drag to orbit — τ, r⃗ and M g⃗ are mutually perpendicular, and the tip of L⃗ really moves on a horizontal circle. Note τ = M g r sin θ grows with the lean, yet ω<sub>p</sub> = M g r / L does not.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec (built exactly as listed) ─────────────────────────────────
// z / y / x axes        → thin cylinder shaft + cone head, black, depthTest off
// top body (teardrop)   → 4 LatheGeometry bands, len 3.6, Rmax 1.35 at h=2.34
//                         (#7FB3C9 / #F2C075 / #7FB3C9 / #A9CEDD)
// top cap disc          → CircleGeometry r=1.10, #A9CEDD
// stem                  → CylinderGeometry(0.26,0.26,0.95) #C6E0EA + cap disc
// spin loop ω           → TubeGeometry 300° arc r=0.52 around stem + cone head, green
// r arrow               → slim cylinder+cone, black, O → CM (len 1.9)
// CM marker             → two crossed thin cylinders, black
// Mg arrow              → cylinder+cone, red #C0392B, down, len 1.0
// τ arrow               → cylinder+cone, orange #EF8420, along r̂×(−ẑ), len ∝ sinθ
// τ leader              → QuadraticBezierCurve3 Line, black
// L arrow               → cylinder+cone, orange, along axis 2.5 → 4.8
// dashed circle         → Line + LineDashedMaterial, black, R=L sinθ at z=L cosθ
// L sinθ radial arrow   → cylinder+cone, orange
// dL = τ dt tangent     → cylinder+cone, orange (label pinned to its tip)
// dφ arc + advanced radius → TubeGeometry arc, black + faint Line
// ω_p arc               → TubeGeometry 138° arc r=2.4 + cone head, black
// θ arc                 → TubeGeometry arc r=0.8 at O, black
// label leaders         → thin faint Lines (CM, Mg)
─────────────────────────────────────────────────────────────────────────── */

const C = {
  blue: 0x7FB3C9, blueLt: 0xA9CEDD, blueVLt: 0xC6E0EA, band: 0xF2C075,
  vec: 0xEF8420, red: 0xC0392B, green: 0x7FA82F, black: 0x141414, faint: 0x9aa0a6
};
const UPV = new THREE.Vector3(0, 1, 0);
const OUT = new THREE.Vector3(0, 0, 1);      // out of the lean plane (screen-left)
const ORIGIN = new THREE.Vector3(0, 0, 0);
const DOWNV = new THREE.Vector3(0, -1, 0);

/* ── lights ───────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.80));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.70);
keyLight.position.set(-4, 6, 5); scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.26);
fillLight.position.set(4, 2, -5); scene.add(fillLight);

/* ── helpers ──────────────────────────────────────────────────────────── */
function killObj(o) {
  o.traverse?.(n => {
    n.geometry?.dispose?.();
    if (Array.isArray(n.material)) n.material.forEach(m => m.dispose?.());
    else n.material?.dispose?.();
  });
}
function clearGroup(g) {
  for (let i = g.children.length - 1; i >= 0; i--) { const c = g.children[i]; g.remove(c); killObj(c); }
}
function makeArrow(color, opt = {}) {
  const shaftR = opt.shaftR ?? 0.033, headL = opt.headL ?? 0.28, headR = opt.headR ?? 0.105;
  const order = opt.order ?? 6;
  const mat = new THREE.MeshStandardMaterial({
    color, roughness: 0.5, metalness: 0.0, depthTest: false, depthWrite: false
  });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, 1, 16), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headL, 20), mat);
  const g = new THREE.Group(); g.add(shaft); g.add(head);
  g.renderOrder = order; shaft.renderOrder = order; head.renderOrder = order;
  g.userData = { shaft, head, headL };
  return g;
}
function setArrow(g, origin, dir, len) {
  const { shaft, head, headL } = g.userData;
  const dv = dir.clone().normalize();
  const L = Math.max(len, headL * 1.05);
  const sl = Math.max(L - headL, 1e-3);
  const q = new THREE.Quaternion().setFromUnitVectors(UPV, dv);
  shaft.scale.set(1, sl, 1);
  shaft.quaternion.copy(q); head.quaternion.copy(q);
  shaft.position.copy(dv).multiplyScalar(sl * 0.5);
  head.position.copy(dv).multiplyScalar(sl + headL * 0.5);
  g.position.copy(origin);
}
function addArcTube(group, pts, color, tubeR, withHead, headL) {
  const mat = new THREE.MeshStandardMaterial({
    color, roughness: 0.6, metalness: 0, depthTest: false, depthWrite: false
  });
  const curve = new THREE.CatmullRomCurve3(pts);
  const mesh = new THREE.Mesh(new THREE.TubeGeometry(curve, Math.max(12, pts.length * 2), tubeR, 8, false), mat);
  mesh.renderOrder = 6; group.add(mesh);
  if (withHead) {
    const hl = headL || 0.22, hr = (headL || 0.22) * 0.44;
    const p1 = pts[pts.length - 1], p0 = pts[pts.length - 2];
    const dv = p1.clone().sub(p0).normalize();
    const cone = new THREE.Mesh(new THREE.ConeGeometry(hr, hl, 16), mat);
    cone.quaternion.setFromUnitVectors(UPV, dv);
    cone.position.copy(p1).add(dv.clone().multiplyScalar(hl * 0.45));
    cone.renderOrder = 6; group.add(cone);
  }
  return mesh;
}
function addPlainLine(group, pts, color, opts = {}) {
  const mat = opts.dashed
    ? new THREE.LineDashedMaterial({ color, dashSize: 0.17, gapSize: 0.13, depthTest: false })
    : new THREE.LineBasicMaterial({ color, depthTest: false, transparent: true, opacity: opts.opacity ?? 1 });
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat);
  if (opts.dashed) line.computeLineDistances();
  line.renderOrder = 5; group.add(line);
  return line;
}

/* ── coordinate axes ──────────────────────────────────────────────────── */
const axesGroup = new THREE.Group(); scene.add(axesGroup);
const axOpt = { shaftR: 0.015, headL: 0.24, headR: 0.072, order: 4 };
const Z_AXIS_LEN = 5.9, Y_AXIS_LEN = 3.2, X_AXIS_LEN = 2.4;
const axZ = makeArrow(C.black, axOpt); axesGroup.add(axZ); setArrow(axZ, ORIGIN, UPV, Z_AXIS_LEN);
const axY = makeArrow(C.black, axOpt); axesGroup.add(axY); setArrow(axY, ORIGIN, new THREE.Vector3(1, 0, 0), Y_AXIS_LEN);
const axX = makeArrow(C.black, axOpt); axesGroup.add(axX); setArrow(axX, ORIGIN, new THREE.Vector3(0, 0, 1), X_AXIS_LEN);

/* ── precession / tilt hierarchy ──────────────────────────────────────── */
const precessGroup = new THREE.Group(); scene.add(precessGroup);
const tiltGroup = new THREE.Group(); precessGroup.add(tiltGroup);

/* ── the top: fat teardrop lathe bands ────────────────────────────────── */
const BODY_LEN = 3.60;
const profCtl = [[0, 0], [0.18, 0.11], [0.40, 0.26], [0.70, 0.46], [1.00, 0.66],
[1.35, 0.88], [1.70, 1.07], [2.00, 1.22], [2.34, 1.35], [2.60, 1.345],
[2.90, 1.305], [3.20, 1.235], [3.40, 1.175], [3.60, 1.10]];
function radAt(h) {
  if (h <= 0) return 0;
  for (let i = 1; i < profCtl.length; i++) {
    if (h <= profCtl[i][0]) {
      const a = profCtl[i - 1], b = profCtl[i];
      const t = (h - a[0]) / (b[0] - a[0]);
      return a[1] + (b[1] - a[1]) * t;
    }
  }
  return profCtl[profCtl.length - 1][1];
}
const CAP_R = radAt(BODY_LEN);
const bodyGroup = new THREE.Group(); tiltGroup.add(bodyGroup);
const bands = [
  { h0: 0.00, h1: 1.55, c: C.blue },
  { h0: 1.55, h1: 2.45, c: C.band },
  { h0: 2.45, h1: 3.25, c: C.blue },
  { h0: 3.25, h1: 3.60, c: C.blueLt }
];
bands.forEach(b => {
  const pts = [];
  const n = 22;
  for (let i = 0; i <= n; i++) {
    const h = b.h0 + (b.h1 - b.h0) * (i / n);
    pts.push(new THREE.Vector2(Math.max(radAt(h), 1e-4), h));
  }
  const mesh = new THREE.Mesh(
    new THREE.LatheGeometry(pts, 80),
    new THREE.MeshStandardMaterial({ color: b.c, roughness: 0.52, metalness: 0.04, side: THREE.DoubleSide })
  );
  bodyGroup.add(mesh);
});
const capMesh = new THREE.Mesh(
  new THREE.CircleGeometry(CAP_R, 80),
  new THREE.MeshStandardMaterial({ color: C.blueLt, roughness: 0.5, side: THREE.DoubleSide })
);
capMesh.rotation.x = -Math.PI / 2; capMesh.position.y = BODY_LEN; bodyGroup.add(capMesh);

/* stem — taller and wider so it reads clearly */
const STEM_R = 0.26, STEM_H = 0.95;
const stem = new THREE.Mesh(
  new THREE.CylinderGeometry(STEM_R, STEM_R, STEM_H, 36),
  new THREE.MeshStandardMaterial({ color: C.blueVLt, roughness: 0.42, metalness: 0.05 })
);
stem.position.y = BODY_LEN + STEM_H / 2; tiltGroup.add(stem);
const stemCap = new THREE.Mesh(
  new THREE.CircleGeometry(STEM_R, 36),
  new THREE.MeshStandardMaterial({ color: 0xdff0f6, roughness: 0.42, side: THREE.DoubleSide })
);
stemCap.rotation.x = -Math.PI / 2; stemCap.position.y = BODY_LEN + STEM_H; tiltGroup.add(stemCap);

/* green spin loop ω around the stem — enlarged */
const SPIN_H = BODY_LEN + 0.45;
const SPIN_R = STEM_R + 0.26;
const spinGroup = new THREE.Group(); tiltGroup.add(spinGroup);
(function buildSpinLoop() {
  const pts = [];
  const a0 = THREE.MathUtils.degToRad(25), a1 = a0 + THREE.MathUtils.degToRad(300);
  for (let i = 0; i <= 54; i++) {
    const a = a0 + (a1 - a0) * (i / 54);
    pts.push(new THREE.Vector3(SPIN_R * Math.cos(a), SPIN_H, -SPIN_R * Math.sin(a)));
  }
  addArcTube(spinGroup, pts, C.green, 0.033, true, 0.26);
})();

/* ── vectors parented to the precession group ─────────────────────────── */
const rArrow = makeArrow(C.black, { shaftR: 0.030, headL: 0.30, headR: 0.110 });
const mgArrow = makeArrow(C.red, { shaftR: 0.030, headL: 0.26, headR: 0.098 });
const tauArrow = makeArrow(C.vec, { shaftR: 0.032, headL: 0.26, headR: 0.100 });
const LArrow = makeArrow(C.vec, { shaftR: 0.040, headL: 0.30, headR: 0.115 });
const radArrow = makeArrow(C.vec, { shaftR: 0.030, headL: 0.26, headR: 0.098 });
const dLArrow = makeArrow(C.vec, { shaftR: 0.030, headL: 0.24, headR: 0.093 });
precessGroup.add(rArrow, mgArrow, tauArrow, LArrow, radArrow, dLArrow);

/* CM cross */
const cmCross = new THREE.Group(); precessGroup.add(cmCross);
(function buildCross() {
  const mat = new THREE.MeshStandardMaterial({ color: C.black, roughness: 0.5, depthTest: false, depthWrite: false });
  [[1, 0, 1], [1, 0, -1]].forEach(dv => {
    const dvec = new THREE.Vector3(dv[0], dv[1], dv[2]).normalize();
    const bar = new THREE.Mesh(new THREE.CylinderGeometry(0.024, 0.024, 0.36, 10), mat);
    bar.quaternion.setFromUnitVectors(UPV, dvec);
    bar.renderOrder = 7;
    cmCross.add(bar);
  });
})();

/* dynamic containers */
const arcsP = new THREE.Group(); precessGroup.add(arcsP);   // rotates with precession
const arcsW = new THREE.Group(); scene.add(arcsW);          // fixed in world

/* τ leader line */
const LEADER_END = new THREE.Vector3(2.85, 0.75, -1.25);
const leader = new THREE.Line(new THREE.BufferGeometry(),
  new THREE.LineBasicMaterial({ color: C.black, depthTest: false }));
leader.renderOrder = 6; scene.add(leader);

/* ── state ────────────────────────────────────────────────────────────── */
const Lmag = 4.8, rCM = 1.9, L_START = 2.50;
const THETA_REF = THREE.MathUtils.degToRad(25);
const SIN_REF = Math.sin(THETA_REF);
let theta = THETA_REF;
let weight = 1.0;                 // relative M g r
let phase = 0;
let playing = false;
let cmP = new THREE.Vector3(), axisP = new THREE.Vector3(), tipP = new THREE.Vector3();
let dphiVal = 0, Rcircle = 0, Hcircle = 0, tauRel = 1, dLlen = 0.5, tauLen = 1.1;

/* anchors for labels */
function anchor(parent) { const o = new THREE.Object3D(); parent.add(o); return o; }
const aCM = anchor(precessGroup), aTheta = anchor(precessGroup), aL = anchor(precessGroup),
  aR = anchor(precessGroup), aMg = anchor(precessGroup), aTau = anchor(precessGroup),
  aLsin = anchor(precessGroup), aDphi = anchor(precessGroup), adL = anchor(precessGroup),
  aOmega = anchor(tiltGroup), aOmegaP = anchor(scene);
aOmega.position.set(-(SPIN_R + 0.42), SPIN_H + 0.12, 0.30);

/* ── rebuild everything that depends on θ and the weight factor ───────── */
function rebuild() {
  const s = Math.sin(theta), c = Math.cos(theta);
  axisP.set(s, c, 0);
  const perp = new THREE.Vector3(c, -s, 0);           // in the lean plane, screen-right
  const tauDir = new THREE.Vector3(0, 0, -1);         // r̂ × (−ẑ)
  tiltGroup.rotation.z = -theta;

  // τ = M g r sinθ  → magnitude really does depend on the lean angle
  tauRel = weight * (s / SIN_REF);
  tauLen = Math.min(1.1 * tauRel, 2.3);
  dLlen = Math.min(0.5 * tauRel, 1.05);

  cmP.copy(axisP).multiplyScalar(rCM);
  setArrow(rArrow, ORIGIN, axisP, rCM);
  cmCross.position.copy(cmP);
  cmCross.rotation.set(0, 0, -theta);
  setArrow(mgArrow, cmP, DOWNV, 1.0);
  setArrow(tauArrow, cmP, tauDir, tauLen);
  setArrow(LArrow, axisP.clone().multiplyScalar(L_START), axisP, Lmag - L_START);

  Rcircle = Lmag * s; Hcircle = Lmag * c;
  tipP.set(Rcircle, Hcircle, 0);
  setArrow(radArrow, new THREE.Vector3(0, Hcircle, 0), new THREE.Vector3(1, 0, 0), Rcircle);
  setArrow(dLArrow, tipP, tauDir, dLlen);
  dphiVal = Math.min(dLlen / Rcircle, 1.1);           // = Mgr/L · dt — independent of θ

  clearGroup(arcsP); clearGroup(arcsW);

  // θ arc at the origin (in the lean plane)
  const tp = [];
  for (let i = 0; i <= 26; i++) { const a = theta * i / 26; tp.push(new THREE.Vector3(0.8 * Math.sin(a), 0.8 * Math.cos(a), 0)); }
  addArcTube(arcsP, tp, C.black, 0.017, false);

  // faint advanced radius + dφ arc
  const adv = new THREE.Vector3(Rcircle * Math.cos(dphiVal), Hcircle, -Rcircle * Math.sin(dphiVal));
  addPlainLine(arcsP, [new THREE.Vector3(0, Hcircle, 0), adv], C.faint, { opacity: 0.8 });
  const ap = [];
  const ar = Math.min(1.0, Rcircle * 0.55);
  for (let i = 0; i <= 18; i++) {
    const a = dphiVal * i / 18;
    ap.push(new THREE.Vector3(ar * Math.cos(a), Hcircle, -ar * Math.sin(a)));
  }
  addArcTube(arcsP, ap, C.black, 0.015, false);

  // dashed precession circle (fixed in world)
  const cp = [];
  for (let i = 0; i <= 170; i++) {
    const a = (i / 170) * Math.PI * 2;
    cp.push(new THREE.Vector3(Rcircle * Math.cos(a), Hcircle, -Rcircle * Math.sin(a)));
  }
  addPlainLine(arcsW, cp, C.black, { dashed: true });

  // ω_p curved arrow, upper-left, around z
  const wp = [];
  const wH = Hcircle + 0.85, wR = 2.4;
  for (let i = 0; i <= 40; i++) {
    const a = THREE.MathUtils.degToRad(112 + (138 * i / 40));
    wp.push(new THREE.Vector3(wR * Math.cos(a), wH, -wR * Math.sin(a)));
  }
  addArcTube(arcsW, wp, C.black, 0.028, true, 0.26);
  aOmegaP.position.set(-wR - 0.50, wH - 0.28, 0.60);

  /* label anchors — spread well apart around the crowded CM region */
  aCM.position.copy(cmP).add(perp.clone().multiplyScalar(-0.62)).add(OUT.clone().multiplyScalar(0.30));
  const half = theta / 2;
  aTheta.position.set(1.05 * Math.sin(half), 1.05 * Math.cos(half), 0).add(OUT.clone().multiplyScalar(0.35));
  aL.position.copy(axisP).multiplyScalar(3.85).add(perp.clone().multiplyScalar(0.55));
  aR.position.copy(axisP).multiplyScalar(0.95).add(OUT.clone().multiplyScalar(0.85));
  aMg.position.copy(cmP).add(new THREE.Vector3(0, -0.72, 0)).add(OUT.clone().multiplyScalar(-0.62));
  aTau.position.copy(cmP).add(tauDir.clone().multiplyScalar(tauLen * 0.55)).add(new THREE.Vector3(0, 0.46, 0));
  aLsin.position.set(Rcircle * 0.50, Hcircle, 0.10);
  aDphi.position.set(ar * Math.cos(dphiVal * 0.5) * 1.25, Hcircle + 0.10, -ar * Math.sin(dphiVal * 0.5) * 1.25);
  adL.position.copy(tipP).add(tauDir.clone().multiplyScalar(dLlen + 0.10));

  /* short leader lines so the crowded labels stay attached to their objects */
  addPlainLine(arcsP, [cmP.clone().add(perp.clone().multiplyScalar(-0.20)), aCM.position.clone()],
    C.faint, { opacity: 0.85 });
  addPlainLine(arcsP, [cmP.clone().add(new THREE.Vector3(0, -0.55, 0)), aMg.position.clone()],
    C.red, { opacity: 0.55 });
  addPlainLine(arcsP, [cmP.clone().add(tauDir.clone().multiplyScalar(tauLen * 0.45)), aTau.position.clone()],
    C.vec, { opacity: 0.5 });

  const ro = document.getElementById('readout');
  if (ro) {
    ro.innerHTML =
      '|L| = ' + Lmag.toFixed(2) + '  (constant)<br>' +
      'L sin θ = ' + Rcircle.toFixed(2) + '<br>' +
      'τ = M g r sin θ = ' + tauRel.toFixed(2) + '<br>' +
      '|dL| = τ dt = ' + dLlen.toFixed(2) + '<br>' +
      'dφ = |dL|/(L sinθ) = ' + THREE.MathUtils.radToDeg(dphiVal).toFixed(1) + '°<br>' +
      'ω_p = M g r / L = ' + (0.62 * weight).toFixed(2) + '  (θ-free)';
  }
}

/* ── camera, then labels ──────────────────────────────────────────────── */
rebuild();
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.80 });
document.getElementById('btnReset').style.display = '';

addLabel('<i><b>z</b></i>', new THREE.Vector3(0, Z_AXIS_LEN + 0.28, 0), { fontSize: '16px', bold: true, offset: [-13, -4] });
addLabel('<i><b>y</b></i>', new THREE.Vector3(Y_AXIS_LEN + 0.22, 0, 0), { fontSize: '16px', bold: true, offset: [13, 9] });
addLabel('<i><b>x</b></i>', new THREE.Vector3(0, 0, X_AXIS_LEN + 0.28), { fontSize: '16px', bold: true, offset: [-7, 15] });
addLabel('<i>O</i>', new THREE.Vector3(0, 0, 0), { fontSize: '15px', offset: [-18, 16] });

const lCM = addLabel('CM', new THREE.Vector3(), { fontSize: '14px', offset: [-20, -10] });
const lTheta = addLabel('<i>&theta;</i>', new THREE.Vector3(), { fontSize: '15px', offset: [8, 2] });
const lOmega = addLabel('<i>&omega;</i>', new THREE.Vector3(), { fontSize: '16px', color: '#5f7f1f', offset: [-12, 0] });
const lOmegaP = addLabel('<i>&omega;</i><sub><i>p</i></sub>', new THREE.Vector3(), { fontSize: '15px', offset: [-18, 0] });
const lL = addLabel('<b><i>L</i></b>&#8407;', new THREE.Vector3(), { fontSize: '17px', color: '#EF8420', bold: true, offset: [18, 4] });
const lr = addLabel('<b><i>r</i></b>&#8407;', new THREE.Vector3(), { fontSize: '17px', bold: true, offset: [-18, 4] });
const lMg = addLabel('<i>M</i><b><i>g</i></b>&#8407;', new THREE.Vector3(), { fontSize: '16px', color: '#C0392B', offset: [-26, 10] });
const lTau = addLabel('<b><i>&tau;</i></b>&#8407;', new THREE.Vector3(), { fontSize: '18px', color: '#EF8420', offset: [10, -12] });
const lLsin = addLabel('<i>L</i> sin<i>&theta;</i>', new THREE.Vector3(), { fontSize: '13px', offset: [-14, 19] });
const lDphi = addLabel('<i>d&phi;</i>', new THREE.Vector3(), { fontSize: '13px', offset: [2, -16] });
const ldL = addLabel('<i>d</i><b><i>L</i></b>&#8407; = <b><i>&tau;</i></b>&#8407; <i>dt</i>',
  new THREE.Vector3(), { fontSize: '14px', color: '#EF8420', offset: [58, -6] });
addLabel('<b><i>&tau;</i></b>&#8407; = <b><i>r</i></b>&#8407; &times; <i>M</i><b><i>g</i></b>&#8407;',
  LEADER_END.clone(), { fontSize: '14px', offset: [66, 6] });

/* ── interactive explanations ─────────────────────────────────────────── */
registerInteractive(bodyGroup, {
  title: 'The spinning top',
  tooltip: 'The top: a teardrop body of revolution leaning by θ',
  body: 'The top is a solid of revolution — pointed at the pivot O, widest near its upper third, with a flat top face. It spins rapidly about its own symmetry axis, which is tilted by θ from the vertical, so its whole angular momentum L lies (to a good approximation) along that axis.'
});
registerInteractive(stem, {
  title: 'Stem and spin ω',
  tooltip: 'ω — the spin about the symmetry axis',
  body: 'The green loop around the stem shows the sense of the rapid spin ω about the symmetry axis. This spin supplies the large angular momentum L that gravity can only redirect, not topple.'
});
registerInteractive(LArrow, {
  title: 'Angular momentum L',
  tooltip: 'L⃗ — constant magnitude, changing direction',
  body: 'L points along the spin axis with |L| = 4.8 (fixed here). Because the torque is always perpendicular to L, only the direction of L changes: its tip travels on the dashed horizontal circle of radius L sin θ.'
});
registerInteractive(tauArrow, {
  title: 'Torque τ = r × M g',
  tooltip: 'τ⃗ — horizontal, perpendicular to r and to g, magnitude M g r sin θ',
  body: 'Gravity acts at the CM with moment arm r. The cross product r × Mg is horizontal and perpendicular to the plane containing the axis and the vertical, so it pushes L sideways rather than down. Its size is M g r sin θ — drag the tilt slider and watch the arrow grow with θ.'
});
registerInteractive(mgArrow, {
  title: 'Weight M g',
  tooltip: 'M g⃗ — straight down at the CM',
